    for (const k of K) n[k] = null;
    Object.assign(n, { kcal, p, c: cb, f, fib, sug, sat, na: Math.round(salt * 400) });
    i++;
    const o = { id: 'wf' + i, name, cat: CAT[c], kw: kw || '', portion, portionLabel: label, n };
